__declspec(noinline) void retdec_trace_i32(const char *label,
                                                  int32_t value) {
    char message[128];
    if (!kinoko_diagnostics_accepts(label)) return;
    retdec_watch_g594();
    retdec_watch_g644();
    wsprintfA(message, "%s:0x%08lX", label, (unsigned long)value);
    retdec_trace(message);
}

