/* Release the shared object held by Actor::m_parent/m_delegate. */


static uint32_t retdec_squirrel_key_hash(const int32_t *key) {
    uint32_t type = (uint32_t)key[0];
    uint32_t data = (uint32_t)key[1];
    if (type == 0x08000010 && data != 0)
        return (uint32_t)*(int32_t *)(data + 24);
    if (type == 0x05000004)
        return (uint32_t)(int32_t)(*(float *)(key + 1));
    if (type == 0x01000008 || type == 0x05000002)
        return data;
    return data >> 3;
}


/* Snapshot the actual SQTable buckets without assuming which bindings were
 * registered.  This is intentionally bounded because a malformed table must
 * not turn diagnostics into another crash. */
void retdec_trace_squirrel_table_entries(const char *label,
                                                int32_t table_ptr) {
    int32_t nodes;
    int32_t capacity;
    int32_t used;
    int32_t bucket_index;
    int32_t entry;
    int32_t chain_length;
    char message[640];

    if (label == NULL || (uint32_t)table_ptr < 0x10000u)
        return;

    __try {
        nodes = *(int32_t *)(intptr_t)(table_ptr + 32);
        capacity = *(int32_t *)(intptr_t)(table_ptr + 36);
        used = *(int32_t *)(intptr_t)(table_ptr + 40);
        wsprintfA(message,
                  "%s:table=0x%08lX nodes=0x%08lX capacity=%ld used=%ld",
                  label, (unsigned long)(uint32_t)table_ptr,
                  (unsigned long)(uint32_t)nodes, (long)capacity, (long)used);
        retdec_trace(message);
        if (nodes == 0 || capacity <= 0 || capacity > 4096)
            return;

        for (bucket_index = 0; bucket_index < capacity; ++bucket_index) {
            /* SQTable stores one 20-byte node per bucket; the node address,
             * rather than its first word, is the bucket head. */
            entry = nodes + 20 * bucket_index;
            chain_length = 0;
            while (entry != 0 && chain_length++ < capacity) {
                int32_t key_type = *(int32_t *)(intptr_t)(entry + 8);
                int32_t key_data = *(int32_t *)(intptr_t)(entry + 12);
                int32_t value_type = *(int32_t *)(intptr_t)(entry + 0);
                int32_t value_data = *(int32_t *)(intptr_t)(entry + 4);
                const char *key_text = "";

                if (key_type == 0x08000010 && key_data != 0)
                    key_text = (const char *)(intptr_t)(key_data + 28);
                wsprintfA(message,
                          "%s:bucket=%ld entry=0x%08lX key=(0x%08lX,0x%08lX) text=%s value=(0x%08lX,0x%08lX) next=0x%08lX",
                          label, (long)bucket_index,
                          (unsigned long)(uint32_t)entry,
                          (unsigned long)(uint32_t)key_type,
                          (unsigned long)(uint32_t)key_data,
                          key_text,
                          (unsigned long)(uint32_t)value_type,
                          (unsigned long)(uint32_t)value_data,
                          (unsigned long)(uint32_t)*(int32_t *)(intptr_t)(entry + 16));
                retdec_trace(message);
                entry = *(int32_t *)(intptr_t)(entry + 16);
            }
            if (entry != 0) {
                retdec_trace_i32("sq-table:cycle-or-long-chain", bucket_index);
                retdec_trace_i32("sq-table:chain-entry", entry);
            }
        }
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        retdec_trace("sq-table:snapshot-fault");
    }
}

/*
 * Squirrel was built with the garbage collector enabled.  Its public
 * sq_addref/sq_release pair therefore owns entries in SQSharedState's
 * RefTable at +24; it does not directly modify the object at data + 4.
 * RefTable is laid out as:
 *   +0 slots, +4 used, +8 nodes, +12 freelist, +16 bucket array.
 * Each node is [type, data, refs, next].
 */


void retdec_trace_ref_watch(const char *label, int32_t shared_state,
                                   int32_t type, int32_t data) {
    int32_t table_ptr = 0;
    int32_t slots = 0;
    int32_t buckets = 0;
    int32_t node = 0;
    int32_t refs = 0;
    int32_t internal = 0;
    int32_t vtable = 0;
    LONG sequence;
    char message[256];

    if (!retdec_is_release_watch_data(data))
        return;
    sequence = InterlockedIncrement(&retdec_release_watch_event_count);
    if (sequence > 4096)
        return;

    __try {
        internal = *(int32_t *)(intptr_t)(data + 4);
        vtable = *(int32_t *)(intptr_t)data;
        if (shared_state != 0) {
            table_ptr = shared_state + 24;
            slots = *(int32_t *)(intptr_t)(table_ptr + 0);
            buckets = *(int32_t *)(intptr_t)(table_ptr + 16);
            if (slots > 0 && slots <= 0x100000 && buckets != 0) {
                int32_t key[2] = { type, data };
                int32_t bucket = buckets + 4 *
                    (int32_t)(retdec_squirrel_key_hash(key) &
                              (uint32_t)(slots - 1));
                node = *(int32_t *)(intptr_t)bucket;
                while (node != 0) {
                    if (*(int32_t *)(intptr_t)(node + 0) == type &&
                        *(int32_t *)(intptr_t)(node + 4) == data) {
                        refs = *(int32_t *)(intptr_t)(node + 8);
                        break;
                    }
                    node = *(int32_t *)(intptr_t)(node + 12);
                }
            }
        }
        wsprintfA(message,
                  "sq-watch:%ld %s type=0x%08lX data=0x%08lX internal=%ld vtable=0x%08lX node=0x%08lX refs=%ld caller=0x%08lX",
                  (long)sequence, label != NULL ? label : "event",
                  (unsigned long)(uint32_t)type,
                  (unsigned long)(uint32_t)data, (long)internal,
                  (unsigned long)(uint32_t)vtable,
                  (unsigned long)(uint32_t)node, (long)refs,
                  (unsigned long)(uintptr_t)_ReturnAddress());
        retdec_trace(message);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        retdec_trace("sq-watch:fault");
    }
}


